with nq as (
  insert into public.questions (stage, question_type, stem, model_answer, explanation, key_points, subject_id, topic_id, paper_id, difficulty, marks,
                                estimated_seconds, origin, status, parent_question_id, variation_type, ai_review, passage_group, passage_position, verified_by, subject_group_id, specialisation_id, image_url)
  values ('ME', 'short_answer', 'In what ways can the central limit theorem be applied to real-world data analysis, and what are its limitations? (5 marks)', 'The central limit theorem states that, for independent observations from any population with finite mean μ and variance σ², the sampling distribution of the sample mean approaches a normal distribution with mean μ and standard error σ/√n as the sample size grows (usually n ≥ 30). Applications: it justifies confidence intervals and z- or t-tests for means and proportions even when the data are not normal (e.g. estimating average household income or poverty rates from national surveys); quality control charts that monitor sample means; A/B testing; and normal approximations to the binomial and Poisson distributions. Limitations: it needs independent, identically distributed observations and finite variance (it fails for very heavy-tailed distributions such as Cauchy); for strongly skewed data or rare events a much larger n is needed; it does not hold well for small samples or dependent data (time series, clustered samples without design adjustment); it applies to means/ sums, not to individual observations or statistics such as extremes; and it gives no protection against bias in sampling.', null, '[{"point": "Statement: sampling distribution of the mean approaches normal as n grows (n ≥ 30), mean μ, SE σ/√n, whatever the population shape", "marks": 1.5}, {"point": "Applications: confidence intervals and z/t tests for means and proportions, survey estimation (national surveys), quality control charts, A/B testing, approximating binomial/ Poisson", "marks": 2}, {"point": "Limitations: needs independent, identically distributed data and finite variance; large n for skewed/ heavy-tailed data; not for small samples, dependent (time series/ clustered) data, extremes/ medians; describes the mean not individual values", "marks": 1.5}]'::jsonb, (select id from public.subjects where slug = 'general-subject-knowledge'),
